import argparse,json,re,html
from pathlib import Path
from collections import Counter
from hashlib import sha256
import build_site,search_pages,build_renditions

def evolve(out):
    out=Path(out);p=out/'participation';boot=json.loads((out/'data/boot.json').read_text());summary=json.loads((p/'summary.json').read_text());coverage=[json.loads(x) for x in (p/'coverage.jsonl').read_text().splitlines()];candidates=[json.loads(x) for x in (p/'candidates.jsonl').read_text().splitlines()]
    if len(coverage)!=boot['records'] or len({x['record_id'] for x in coverage})!=boot['records']:raise ValueError('Coverage mismatch')
    if summary['dataset_revision']!=boot['publication']['dataset_revision']:raise ValueError('Dataset mismatch')
    participation=[c for c in candidates if c['category']=='possible-participation'];topics={}
    for c in participation:
        for t in c['topics']:topics.setdefault(t,set()).add(c['representation_sha256'])
    metrics={'schema':'participation-metrics-v2','app_revision':boot['app_revision'],'dataset_revision':summary['dataset_revision'],'scope':'possible-participation cues only; officials and ambiguous roles remain; not actual comments or population demand','reviewed_events':0,'topic_text_versions':{k:len(v) for k,v in topics.items()},'all_cue_categories':dict(Counter(c['category'] for c in candidates)),'historical_completeness':False}
    (p/'metrics.json').write_text(json.dumps(metrics,indent=2))
    years=Counter()
    for r in coverage:
        m=re.search(r'/(\d{4})/',r['path']);years[m.group(1) if m else 'unknown']+=1
    cp=p/'coverage.html';cp.write_text(cp.read_text().replace('</main>','<section><h2>Path-year coverage, not verified meeting dates</h2><pre>'+html.escape(json.dumps(dict(sorted(years.items())),indent=2))+'</pre><p>Official expected-meeting inventory is not supplied. Completeness percentage cannot be calculated. Fireflies is not imported. Duplicate meetings, cancellations and missing sources require reconciliation.</p></section></main>'))
    ranked=sorted(metrics['topic_text_versions'].items(),key=lambda x:(-x[1],x[0]));cards=''
    for key,n in ranked:
        issue=sha256(key.encode()).hexdigest();url='../issues/'+issue+'/'
        label=html.escape(key)+' — '+str(n)+' candidate text versions'
        cards+='<li>'+('<a href="'+url+'">'+label+'</a>' if (out/'issues'/issue/'index.html').exists() else label)+'</li>'
    mp=out/'audiences/metrics-first.html';text=mp.read_text();text=re.sub(r'Exploratory candidate-topic coverage:.*?all source records remain available\.','This exploratory rendition prioritizes topic matches near possible-participation cues only. Invitations and no-response cues are excluded from this ranking. Speaker roles remain unverified; these are not actual-comment totals or population preferences.',text,count=1,flags=re.S)
    text=text.replace('<main>','<main><section><h2>Participation-candidate topic navigation</h2><p>This changes navigation only, never the facts. All issues remain available below.</p><ol>'+cards+'</ol><a href="participation/metrics.json">Metric definitions and revision</a></section>',1);mp.write_text(text)
    controls='''<section><h2>Search and inspect participation candidates</h2><p>Search titles, paths, cue words and topic tags. Results are unreviewed discovery leads. The full metadata download loads once; rendering is limited to 25 results per page. Source text loads only when requested.</p><label for="q">Search candidate metadata</label><input id="q"><label for="kind">Cue category</label><select id="kind"><option value="">All categories</option><option value="possible-participation">Possible participation</option><option value="invitation">Invitations</option><option value="possible-no-response">Possible no response</option></select><button id="apply" type="button">Apply filters</button><p id="result-status" role="status">Loading metadata…</p><div id="results"></div><button id="previous" type="button">Previous</button><button id="next" type="button">Next</button></section><section><h2>Source context</h2><p id="source-status" role="status">Select a candidate.</p><pre id="source-context" tabindex="0"></pre><p id="source-link"></p></section><section><h2>Local review desk</h2><p>No decisions are published or sent to a server. Exported decisions remain drafts requiring maintainer review. No personal contact information is requested.</p><label for="reviewer">Accountable reviewer ID</label><input id="reviewer"><label for="decision">Decision</label><select id="decision"><option value="needs_review">Needs review</option><option value="rejected">Reject</option><option value="confirmed_public_comment">Confirm public comment</option></select><label for="role">Verified role</label><select id="role"><option value="unknown">Unknown</option><option value="public_commenter">Public commenter</option><option value="official">Official</option><option value="staff">Staff</option></select><label for="event">Resolved meeting and speaking-turn key</label><input id="event"><label for="event-date">Verified event date</label><input id="event-date" type="date"><label for="reference">Original source reference, page or timestamp checked</label><input id="reference"><label><input id="checked" type="checkbox"> I checked source context and public-commenter role.</label><button id="add-review" type="button">Add draft review</button><button id="export-review" type="button">Export review drafts</button><button id="clear-review" type="button">Clear session</button><p id="review-status" role="status">No session reviews.</p></section><noscript><p>Interactive filters require JavaScript. The paginated candidate pages and full static archive remain available without it.</p></noscript>'''
    script=r'''<script>
(()=>{'use strict';const $=x=>document.getElementById(x);let all=[],filtered=[],page=0,selected=null;const reviews=new Map();function node(tag,text,parent){const n=document.createElement(tag);n.textContent=text;parent.append(n);return n;}function render(){const box=$('results');box.replaceChildren();for(const c of filtered.slice(page*25,page*25+25)){const row=node('article','',box);node('h3',c.title,row);node('p',c.category+'; '+c.path+'; role/date unresolved',row);node('p','Candidate topics: '+c.topics.join(', '),row);const b=node('button','Load and hash-check source context',row);b.type='button';b.onclick=()=>open(c);} $('result-status').textContent=filtered.length+' unreviewed candidates; page '+(page+1)+' of '+Math.max(1,Math.ceil(filtered.length/25));$('previous').disabled=page===0;$('next').disabled=(page+1)*25>=filtered.length;}function filter(){const q=$('q').value.toLowerCase(),k=$('kind').value;filtered=all.filter(c=>(!k||c.category===k)&&(!q||(c.title+' '+c.path+' '+c.cue+' '+c.topics.join(' ')).toLowerCase().includes(q)));page=0;render();}async function open(c){selected=null;$('source-context').textContent='';$('source-link').replaceChildren();$('source-status').textContent='Loading complete static representation…';try{if(!/^[a-f0-9]{64}$/.test(c.record_id))throw Error('Invalid ID');const u='../records/'+c.record_id+'/',r=await fetch(u);if(!r.ok)throw Error('Source unavailable');const doc=new DOMParser().parseFromString(await r.text(),'text/html'),pre=doc.querySelector('article pre');if(!pre)throw Error('Missing source text');const text=pre.textContent,hash=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(text)))).map(x=>x.toString(16).padStart(2,'0')).join('');if(hash!==c.representation_sha256)throw Error('Representation hash mismatch');$('source-context').textContent=Array.from(text).slice(c.context_start_char,c.context_end_char_exclusive).join('');$('source-status').textContent='Complete representation hash verified. Context lines '+c.start_line+'–'+c.end_line+'. Public role, event date and recording timestamp remain unverified.';const a=node('a','Open complete source',$('source-link'));a.href=u;selected=c;$('checked').checked=false;$('decision').value='needs_review';$('role').value='unknown';$('event').value='';$('event-date').value='';$('reference').value='';}catch(e){$('source-status').textContent=e.message;}}$('apply').onclick=filter;$('previous').onclick=()=>{if(page){page--;render();}};$('next').onclick=()=>{if((page+1)*25<filtered.length){page++;render();}};$('add-review').onclick=()=>{try{if(!selected)throw Error('Verify a source first');const v={candidate_id:selected.id,representation_sha256:selected.representation_sha256,decision:$('decision').value,role:$('role').value,reviewer:$('reviewer').value.trim(),event_key:$('event').value.trim(),event_date:$('event-date').value||null,source_reference:$('reference').value.trim(),source_checked:$('checked').checked,reviewed_at:new Date().toISOString(),publication_status:'draft_requires_maintainer_review'};if(!v.reviewer)throw Error('Reviewer ID required');if(v.decision==='confirmed_public_comment'&&(!v.source_checked||v.role!=='public_commenter'||!v.event_key||!v.event_date||!v.source_reference))throw Error('Confirmation needs public role, source check, event key/date and source reference');reviews.set(v.candidate_id,v);$('review-status').textContent=reviews.size+' draft reviews in this session; not published.';}catch(e){$('review-status').textContent=e.message;}};$('export-review').onclick=()=>{if(!reviews.size){$('review-status').textContent='No review drafts to export.';return;}const url=URL.createObjectURL(new Blob([JSON.stringify([...reviews.values()],null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='participation-review-drafts.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};$('clear-review').onclick=()=>{reviews.clear();$('review-status').textContent='Session cleared.';};fetch('candidates.jsonl').then(r=>{if(!r.ok)throw Error('Metadata unavailable');return r.text();}).then(t=>{all=t.trim()?t.trim().split(/\r?\n/).map(l=>JSON.parse(l)):[];filter();}).catch(e=>{$('result-status').textContent=e.message;});})();
</script>'''
    home=p/'index.html';home.write_text(home.read_text().replace('</main>',controls+'</main>').replace('</body>',script+'</body>'))
    if len({c['id'] for c in candidates})!=len(candidates):raise ValueError('Duplicate candidate identities')
    modes=[m[0] for m in build_renditions.MODES]+['metrics-first']
    for mode in modes:
        text=(out/'audiences'/(mode+'.html')).read_text()
        for control in ('id="record-text"','id="add-evidence"','id="generate"','<base href="../">'):
            if control not in text:raise ValueError('Missing control '+mode+' '+control)
    if sum(f.stat().st_size for f in out.rglob('*') if f.is_file())>256*1024*1024:raise ValueError('Site size limit exceeded')
    (p/'build-verification.json').write_text(json.dumps({'schema':'rendition-structural-checks-v1','app_revision':boot['app_revision'],'coverage_identity_check':True,'candidate_identity_check':True,'rendition_controls_checked':modes,'browser_interaction_tests':'not_run_by_this_module','historical_completeness':False},indent=2))

if __name__=='__main__':
    p=argparse.ArgumentParser();p.add_argument('--dataset-repo',required=True);p.add_argument('--out',required=True);p.add_argument('--revision',required=True);a=p.parse_args()
    build_site.build(a.dataset_repo,a.out,a.revision)
    search_pages.build(a.dataset_repo,a.out)
    build_renditions.build(a.dataset_repo,a.out)
    evolve(a.out)
